// Simulating the discount logic
const THRESHOLD_MINOR = 10_000;

function discountMinor(subtotalMinor, memberSince) {
  const rate = subtotalMinor > THRESHOLD_MINOR ? 0.1 : 0.05;
  const years = new Date('2026-09-01').getFullYear() - memberSince;
  const loyalty = Math.min(years, 5) * 0.01;
  return Math.round(subtotalMinor * (rate + loyalty));
}

// Test cases from test/discount.test.js
console.log("Test 1 - below threshold:");
console.log("  Expected: 250, Got:", discountMinor(5000, 2026));

console.log("Test 2 - at threshold:");
console.log("  Expected: 1000, Got:", discountMinor(10000, 2026));

console.log("Test 3 - 5 year member:");
console.log("  Expected: 1500, Got:", discountMinor(10000, 2021));

console.log("Test 4 - loyalty capped:");
console.log("  Expected: 1500, Got:", discountMinor(10000, 2010));

// Debug test 2
console.log("\nDebug Test 2:");
console.log("  10000 > 10000? ", 10000 > 10000);
console.log("  rate would be: ", 10000 > 10000 ? 0.1 : 0.05);
console.log("  calculation: 10000 * (0.05 + 0) =", 10000 * 0.05);
EOF
